1	package app
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/anthnel/devdesk/internal/ui/shortcut"
8		"github.com/anthnel/devdesk/internal/ui/theme"
9		"github.com/charmbracelet/lipgloss"
10	)
11	
12	// HeaderView is the interface each view must implement to provide the header data
13	type HeaderView interface {
14		GetShortcuts() shortcut.Shortcuts
15		GetTitle() string
16		GetIcon() string
17		GetHeaderInfo(context string) []shortcut.HeaderInfo
18	}
19	
20	// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
21	// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
22	type FooterView interface {
23		GetFooterHeight() int          // current footer height in lines (0 if no footer)
24		RenderFooter(width int) string // rendered footer content
25	}
26	
27	// FramelessView is implemented by a view that draws its own frames and wants
28	// none around it. The default — framed — is the safe behavior: a view that
29	// does not implement this is framed like all the others, unlike HeaderView
30	// whose missing half silently renders an empty title.
31	//
32	// Only one view implements it (the dashboard), and that is deliberate: every
33	// other view frames a single object — a table, a form.
34	type FramelessView interface {
35		Frameless() bool
36	}
37	
38	// headerMinHeight is the fixed header height (without the command line).
39	const headerMinHeight = 7
40	
41	// ASCII logo for the header
42	var logoLines = []string{
43		`    ____            ____            __  `,
44		`   / __ \___ _   __/ __ \___  _____/ /__`,
45		`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
46		` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
47		`/_____/\___/|___/_____/\___/____/_/|_|  `,
48	}
49	
50	const logoWidth = 40 // max width of a logo line
51	
52	// renderHeader generates the header (fixed height) followed by the command line (1 line).
53	func (a *App) renderHeader() string {
54		if view, ok := a.views[a.currentView]; ok {
55			if headerView, implementsHeaderView := view.(HeaderView); implementsHeaderView {
56				shortcuts := headerView.GetShortcuts()
57				if a.commandMode && a.viewPicker {
58					shortcuts = viewPickerShortcuts()
59				}
60				info := headerView.GetHeaderInfo(a.currentContext)
61	
62				header := renderHeaderContent(info, shortcuts, a.width)
63	
64				pad := theme.Bg(" ")
65				var cmdLine string
66				if a.commandMode && a.viewPicker {
67					cmdLine = a.renderViewPicker(a.width)
68				} else if a.commandMode {
69					cmdLine = pad + theme.CommandLineStyle.Width(a.width-2).Render(a.renderCommandLineWithCompletion()) + pad
70				} else {
71					cmdLine = pad + theme.CommandLineInactiveStyle.Width(a.width-2).Render("❯") + pad
72				}
73	
74				// A blank line under the command line keeps it from touching the title rule.
75				return header + "\n" + theme.EmptyLineBg(a.width) + "\n" + cmdLine + "\n" + theme.EmptyLineBg(a.width)
76			}
77		}
78	
79		return ""
80	}
81	
82	// renderHeaderContent generates the header block with a fixed height (headerMinHeight).
83	// Layout: 3 columns — info (25%), shortcuts (flexible), logo (fixed width).
84	func renderHeaderContent(info []shortcut.HeaderInfo, shortcuts shortcut.Shortcuts, width int) string {
85		innerWidth := width - 2 // 1 padding each side
86	
87		// Column widths
88		col1Width := innerWidth / 4
89		col3Width := logoWidth
90		col2Width := innerWidth - col1Width - col3Width
91		if col2Width < 0 {
92			col2Width = 0
93		}
94	
95		// Build column 1: key-value info lines
96		col1Lines := buildInfoLines(info, col1Width)
97	
98		// Build column 2: shortcuts
99		col2Lines := buildShortcutLines(shortcuts, col2Width)
100	
101		// Build column 3: logo (centered vertically — 1 empty line on top since 6 logo lines / 7 header lines)
102		col3Lines := buildLogoLines(col3Width)
103	
104		// Assemble rows
105		rows := make([]string, headerMinHeight)
106		for i := 0; i < headerMinHeight; i++ {
107			c1 := ""
108			if i < len(col1Lines) {
109				c1 = col1Lines[i]
110			}
111			c2 := ""
112			if i < len(col2Lines) {
113				c2 = col2Lines[i]
114			}
115			c3 := ""
116			if i < len(col3Lines) {
117				c3 = col3Lines[i]
118			}
