44	// full inner width so no line shows the terminal's own background (Rule 115).
45	func (a *App) renderBody() string {
46		content := "View not found: " + string(a.currentView)
47		if view, ok := a.views[a.currentView]; ok {
48			content = view.View()
49		}
50	
51		innerWidth := a.viewport.Width - 2 // -2 for the borders
52		if a.frameless() {
53			innerWidth = a.viewport.Width
54		}
55		a.viewport.SetContent(lipgloss.NewStyle().
56			Background(theme.ColorBackground).
57			Foreground(theme.ColorText).
58			Width(innerWidth).
59			Render(content))
