61		body := a.viewport.View()
62	
63		// Rule 136: with a filter bar below it, the viewport's bottom corners become
64		// T-junctions so the two form one closed rectangle.
65		if view, ok := a.views[a.currentView]; ok {
66			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
