338	// layoutOnce sizes the viewport against the active view's footer and hands the
339	// view its content height. It returns true when the footer height changed
340	// along the way, i.e. when a second pass says something different.
341	func (a *App) layoutOnce(width, height int) (changed bool) {
342		// Rule 124: footer height is deducted from the viewport (tabs + optional info line)
343		footerHeight := a.getFooterHeight()
344		a.lastFooterHeight = footerHeight
345	
346		headerHeight := lipgloss.Height(a.renderHeader())
347		availableHeight := height - headerHeight - footerHeight
348		a.viewport.Width = width
349		a.viewport.Height = availableHeight - 1 // -1 for the custom title border line
350	
351		// Propagate to the active view. The viewport has 1 border (bottom only),
352		// the view must know the inner height. A frameless view has none and
353		// reclaims the line.
354		viewportBorderHeight := 1
355		a.viewport.Style = viewportStyle()
356		if a.frameless() {
357			viewportBorderHeight = 0
358			a.viewport.Style = framelessViewportStyle()
359		}
360		contentHeight := max((availableHeight-1)-viewportBorderHeight, 1)
361		if view, ok := a.views[a.currentView]; ok {
362			updatedView, _ := view.Update(tea.WindowSizeMsg{Width: width, Height: contentHeight})
363			a.views[a.currentView] = updatedView
364		}
365	
366		return a.getFooterHeight() != footerHeight
367	}
368	
369	// getFooterHeight returns the current footer height for the active view.
370	func (a *App) getFooterHeight() int {
371		if view, ok := a.views[a.currentView]; ok {
372			if fv, ok := view.(FooterView); ok {
373				return fv.GetFooterHeight()
374			}
375		}
376		return 0
377	}
378	
379	// reinitializeViews drops every view so they are rebuilt against the current
380	// config, and returns the init cmd for the one on screen.
381	func (a *App) reinitializeViews() tea.Cmd {
382		log.Printf("Reinitializing views with new config")
383		a.views = make(map[command.ViewType]tea.Model)
384		a.createView(a.currentView)
385	
386		var initCmd tea.Cmd
387		if view, ok := a.views[a.currentView]; ok {
388			initCmd = view.Init()
389		}
390		log.Printf("Views reinitialized successfully")
391		return initCmd
392	}
