211	// handleContextListKeyMsg handles key presses in the context selection overlay
212	func (a *App) handleContextListKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
213		switch msg.String() {
214		case "esc", "q":
215			a.showContextList = false
216		case "up":
217			a.contextSelectedIdx = max(a.contextSelectedIdx-1, 0)
218		case "down":
219			a.contextSelectedIdx = min(a.contextSelectedIdx+1, len(a.contextList)-1)
220		case "enter":
221			if len(a.contextList) > 0 {
222				a.showContextList = false
223				return a, a.switchContext(a.contextList[a.contextSelectedIdx])
224			}
225		}
226		return a, nil
227	}
